#include <iostream>
#include <fstream>

int main() {
    std::ofstream salida{"muestra_lgp.txt"};
    if (!salida) {
        std::cout << "Erreur d'ouverture en écriture";
        return 1;
    }
    salida << "2 5";
    salida.close();
    if (!salida) {
        std::cout << "Erreur d'écriture";
        return 1;
    }
    std::ifstream entrada{"muestra_lgp.txt"};
    if (!entrada) {
        std::cout << "Erreur d'ouverture en lecture";
        return 1;
    }
    int primero{0};
    int segundo{0};
    if (!(entrada >> primero >> segundo)) {
        std::cout << "Format invalide";
        return 1;
    }
    std::cout << "Total=" << primero + segundo;
    return 0;
}

